<div class="rounded-xl border bg-card"><div class="flex items-center justify-between p-4 pb-3"><h3 class="font-semibold text-sm">{{ $heading }}</h3><x-capstone::feature-link x-show="groups.length" :href="$link" class="text-xs text-primary hover:underline flex items-center gap-1">View All <x-capstone::icon name="ArrowRight" class="h-3 w-3" /></x-capstone::feature-link></div><p x-show="!groups.length" class="text-sm text-muted-foreground text-center py-4">{{ $empty }}</p><div class="divide-y divide-border"><template x-for="group in groups.slice(0,5)" :key="group.id"><div class="flex items-center justify-between p-4"><div class="min-w-0 flex-1"><x-capstone::feature-link :href="$link" class="text-sm font-medium hover:text-primary truncate block" x-text="group.code || ('Group '+group.id)"></x-capstone::feature-link><p class="text-xs text-muted-foreground truncate mt-0.5" x-text="group.period ? 'Period: '+group.period.name : group.status"></p></div><x-capstone::badge variant="outline" class="ml-3 shrink-0" x-text="group.status || 'Unknown'" /></div></template></div></div>
